const { itemType, itemTypeName } = options;
const isPolymorphic = ArasModules.metadata.itemType.isPolymorphic(itemType.id);
if (isPolymorphic) {
	return {
		disabled: true,
		hidden: false
	};
}

const state = options.getState();
const selectedConfigIds = state.grid.selectedRows.reduce((result, id) => {
	const isNew = ArasModules.item.isNew(itemTypeName, id);
	if (!isNew) {
		result.push(options.rows.get(id, 'config_id'));
	}

	return result;
}, []);

if (!selectedConfigIds.length) {
	return {
		disabled: true,
		hidden: false
	};
}

const props = options.getProps();
const selectedFavorites = options.favorites.filterFavorites(props.favorites, 'Item', favorite =>
	selectedConfigIds.includes(favorite.additional_data.id));
const hidden = selectedConfigIds.length === selectedFavorites.length;
const disabled = state.grid.selectedRows.length > 1;

return {
	disabled,
	hidden
};
